class Solution:
    def makeSimilar(self, nums: List[int], target: List[int]) -> int:
        a = [sorted(x for x in nums if x % 2), sorted(x for x in nums if x % 2 == 0)]
        b = [sorted(x for x in target if x % 2), sorted(x for x in target if x % 2 == 0)]
        return sum(abs(x - y) for i in range(2) for x, y in zip(a[i], b[i])) // 4

