class Solution {
    public long makeSimilar(int[] nums, int[] target) {
        List<Long>[] a = new List[]{new ArrayList<Long>(), new ArrayList<Long>()};
        List<Long>[] b = new List[]{new ArrayList<Long>(), new ArrayList<Long>()};
        for (int x : nums) a[x & 1].add((long) x);
        for (int x : target) b[x & 1].add((long) x);
        long ans = 0;
        for (int p = 0; p < 2; p++) {
            Collections.sort(a[p]); Collections.sort(b[p]);
            for (int k = 0; k < a[p].size(); k++) ans += Math.abs(a[p].get(k) - b[p].get(k));
        }
        return ans / 4;
    }
}

