var makeSimilar = function(nums, target) {
    const a = [[], []], b = [[], []];
    for (const x of nums) a[x & 1].push(x);
    for (const x of target) b[x & 1].push(x);
    let ans = 0;
    for (const p of [0, 1]) {
        a[p].sort((x, y) => x - y); b[p].sort((x, y) => x - y);
        for (let k = 0; k < a[p].length; k++) ans += Math.abs(a[p][k] - b[p][k]);
    }
    return ans / 4;
};
